import numpy as np
import os
from unittest.mock import patch


@patch(target="os.getcwd", new=np.array([-5.5, 3.0]))
def test_patch_array(mock_cwd):
    assert isinstance(mock_cwd, np.ndarray)


@patch("os.getcwd")
def test_patch_default(mock_cwd):
    mock_cwd.return_value = "x"
    assert os.getcwd() == "x"


@patch(target="os.getcwd", new=np.array([-5.5, 3.0]))
@patch(target="os.listdir", new=np.array([1, 2, 3]))
def test_patch_two_arrays(mock_listdir):
    assert isinstance(mock_listdir, np.ndarray)


@patch(target="os.getcwd", new="not-an-array")
def test_patch_plain_value(value):
    assert value == "not-an-array"
